mapper.select:
select u.id, info.id as info_id, info.last_name as lastName, info.first_name as firstName, info.avatar_file_id as avatarFileId ,f.id as f_id, f.file_url as f_file_url,f.name as f_name, f.save_type as f_save_type ,cc.mid as mid, cc.message as m_message, cc.create_time as m_create_time,count(m.id) as newMesCount from gc_user_access ua left join gc_access access on access.id = ua.access_id
left join gc_user_access uaTar on uaTar.access_id = access.admin_id
left join gc_access accessStu on accessStu.admin_id=access.id left join gc_user_access uaTar on uaTar.access_id = accessStu.id
left join gc_group g ON g.group_access_ids::jsonb @> to_jsonb(uaTar.id::integer) and g.master_id = uaTar.master_id
left join gc_user u on u.id = uaTar.user_id left join gc_user_info info on info.id= u.info_id left join sys_file f on f.id = info.avatar_file_id left join gc_user_message m on m.user_id=u.id and m.target_user_id = ua.user_id and m.master_id=ua.master_id and read_state=0
left join ( select a.uid, um.id,um.message,um.create_time,mid from gc_user_message um, ( select u.id as uid, u.username, max(m.id) as mid from gc_user u left join gc_user_message m on (m.target_user_id = u.id or m.user_id=u.id) and u.id !=#{userId} where m.id in ( select max(id) from gc_user_message m where (m.target_user_id= #{userId} or m.user_id =#{userId}) and master_id =#{masterId} group by m.target_user_id,m.user_id
) group by u.id ) a where um.id=mid) cc on cc.uid=u.id
where ua.master_id = #{masterId} and ua.user_id =#{userId}
and g.id=#{groupId}
and u.id is not null group by m.user_id, u.id order by newMesCount desc, m_create_time desc

select
, u.password,f.id as f_id,f.name as f_name,f.file_url as f_file_url,f.save_type as f_save_type
from gc_user u left join gc_user_info ui on ui.id=u.info_id left join sys_file f on ui.avatar_file_id=f.id where u.id=#{userId}

SELECT u.id as user_id,u.username as user_name, a.sub_permission as sub_permission
FROM gc_user u LEFT JOIN gc_user_video_play uvp ON uvp.user_id = u.id LEFT JOIN gc_user_info ui ON ui.id = u.info_id LEFT JOIN gc_user_access ua ON ua.user_id = u.id LEFT JOIN gc_user_access_permission a ON ua.id = a.user_access_id LEFT JOIN gc_access ac ON ac.id = ua.access_id left join gc_access ac2 on ac.admin_id = ac2.id LEFT JOIN gc_video v ON uvp.video_id = v.id LEFT JOIN gc_subject s ON v.sub_id = s.id
${ew.customSqlSegment}

SELECT subject_id as "subjectId", SUM(SUBJECT_USERS) as "subjectUsers" FROM ( SELECT S.ID AS SUBJECT_ID, COUNT(USER.ID) AS SUBJECT_USERS,S.master_id as master_id FROM GC_USER USER LEFT JOIN GC_USER_ACCESS UA ON USER.ID = UA.USER_ID LEFT JOIN GC_USER_ACCESS_PERMISSION UAP ON UA.ID = UAP.USER_ACCESS_ID LEFT JOIN GC_SUBJECT S ON UAP.SUB_PERMISSION::jsonb @> to_jsonb(S.ID::integer) WHERE UA.master_id=#{masterId} and S.ID IN
#{id}
GROUP BY S.ID ) T WHERE SUBJECT_ID IS NOT NULL group by SUBJECT_ID
